{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2193-10-21 16:10:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I’ll be taking care of you during your stay. Can you tell me what brought you in today?"
    },
    {
      "turn_number": 2,
      "time": "2193-10-21 16:11:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’ve been having this sore on my left foot that won’t heal. It started after I hit my toe in the shower about a month ago."
    },
    {
      "turn_number": 3,
      "time": "2193-10-21 16:12:00",
      "speaker": "Doctor",
      "text": "I see. And what happened after you hit it?"
    },
    {
      "turn_number": 4,
      "time": "2193-10-21 16:13:00",
      "speaker": "Patient",
      "text": "It turned purple, and then my toenail fell off. It bleeds sometimes. I didn’t feel much pain because of my neuropathy, but my podiatrist said it looked bad and sent me here."
    },
    {
      "turn_number": 5,
      "time": "2193-10-21 16:14:00",
      "speaker": "Doctor",
      "text": "Thank you. Given your history of diabetes and kidney disease, foot ulcers can be serious. We’ll need to check the blood flow to your leg and treat any infection."
    },
    {
      "turn_number": 6,
      "time": "2193-10-21 16:15:00",
      "speaker": "Patient",
      "text": "Will I need surgery?"
    },
    {
      "turn_number": 7,
      "time": "2193-10-21 16:16:00",
      "speaker": "Doctor",
      "text": "Not yet. Tomorrow, you’ll have a test called an angiogram to look at the blood vessels in your leg. After that, the vascular surgeon will decide if you need a procedure."
    },
    {
      "turn_number": 8,
      "time": "2193-10-21 16:17:00",
      "speaker": "Patient",
      "text": "Okay. I’m on dialysis too—will that affect anything?"
    },
    {
      "turn_number": 9,
      "time": "2193-10-21 16:18:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll coordinate your dialysis. You’re scheduled for it the day after your angiogram. We’ll also monitor your kidney function closely."
    },
    {
      "turn_number": 10,
      "time": "2193-10-21 16:19:00",
      "speaker": "Patient",
      "text": "And my heart? I have a mechanical valve and take warfarin."
    },
    {
      "turn_number": 11,
      "time": "2193-10-21 16:20:00",
      "speaker": "Doctor",
      "text": "We know about that. We’ll start a heparin drip to keep your blood thin while we adjust your warfarin. Your INR will be checked daily."
    },
    {
      "turn_number": 12,
      "time": "2193-10-21 16:21:00",
      "speaker": "Patient",
      "text": "Good. I don’t want another clot."
    },
    {
      "turn_number": 13,
      "time": "2193-10-21 16:22:00",
      "speaker": "Doctor",
      "text": "We’ll make sure you’re protected. For now, we’ll admit you, start IV antibiotics, and get some tests done."
    },
    {
      "turn_number": 14,
      "time": "2193-10-21 20:30:00",
      "speaker": "Doctor",
      "text": "We just got your chest X-ray back. It shows mild fluid in your lungs, but it’s stable. Your dialysis catheter and heart device are in good position."
    },
    {
      "turn_number": 15,
      "time": "2193-10-21 20:31:00",
      "speaker": "Patient",
      "text": "Is that why I sometimes feel short of breath?"
    },
    {
      "turn_number": 16,
      "time": "2193-10-21 20:32:00",
      "speaker": "Doctor",
      "text": "Possibly. Your heart isn’t pumping as strongly as it should, so fluid can build up. We’ll manage that with your dialysis and medications."
    },
    {
      "turn_number": 17,
      "time": "2193-10-22 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Today is your angiogram. You’ll be taken shortly. Any questions before you go?"
    },
    {
      "turn_number": 18,
      "time": "2193-10-22 08:01:00",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 19,
      "time": "2193-10-22 08:02:00",
      "speaker": "Doctor",
      "text": "You’ll be given sedation. You might feel some pressure, but not sharp pain. The team will use ultrasound to guide the catheter in your groin."
    },
    {
      "turn_number": 20,
      "time": "2193-10-22 08:03:00",
      "speaker": "Patient",
      "text": "Okay, I trust you."
    },
    {
      "turn_number": 21,
      "time": "2193-10-22 14:00:00",
      "speaker": "Doctor",
      "text": "The angiogram is done. It went well. There’s a severe blockage in the artery of your left leg, which explains the poor healing."
    },
    {
      "turn_number": 22,
      "time": "2193-10-22 14:01:00",
      "speaker": "Patient",
      "text": "Will I need surgery then?"
    },
    {
      "turn_number": 23,
      "time": "2193-10-22 14:02:00",
      "speaker": "Doctor",
      "text": "Yes, the vascular surgeon recommends a left femoral endarterectomy. It’s scheduled for next week. You’ll be readmitted two days before to start heparin."
    },
    {
      "turn_number": 24,
      "time": "2193-10-22 14:03:00",
      "speaker": "Patient",
      "text": "And the infection?"
    },
    {
      "turn_number": 25,
      "time": "2193-10-22 14:04:00",
      "speaker": "Doctor",
      "text": "We’re continuing IV vancomycin. The urine culture showed contamination, so we’re focusing on the foot. Podiatry saw you and agreed to keep the offloading dressing."
    },
    {
      "turn_number": 26,
      "time": "2193-10-22 14:05:00",
      "speaker": "Patient",
      "text": "I don’t want to lose my toe."
    },
    {
      "turn_number": 27,
      "time": "2193-10-22 14:06:00",
      "speaker": "Doctor",
      "text": "We’re doing everything to save it. Good blood flow after surgery and antibiotics should help it heal."
    },
    {
      "turn_number": 28,
      "time": "2193-10-23 09:00:00",
      "speaker": "Doctor",
      "text": "You’re due for dialysis today. How are you feeling?"
    },
    {
      "turn_number": 29,
      "time": "2193-10-23 09:01:00",
      "speaker": "Patient",
      "text": "Okay. My foot feels the same. The groin site is a little sore."
    },
    {
      "turn_number": 30,
      "time": "2193-10-23 09:02:00",
      "speaker": "Doctor",
      "text": "That’s normal. We’ll keep an eye on it. Your labs show your INR is improving—now at 2.8. We’ll stop the heparin soon."
    },
    {
      "turn_number": 31,
      "time": "2193-10-24 08:30:00",
      "speaker": "Doctor",
      "text": "Your INR is now 3.1—perfect. We’ve stopped the heparin drip. You can stay on warfarin safely."
    },
    {
      "turn_number": 32,
      "time": "2193-10-24 08:31:00",
      "speaker": "Patient",
      "text": "Great. Can I eat regular food now?"
    },
    {
      "turn_number": 33,
      "time": "2193-10-24 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, you’re on a regular diet. We’ll keep monitoring your potassium and phosphorus due to your kidney disease."
    },
    {
      "turn_number": 34,
      "time": "2193-10-25 15:00:00",
      "speaker": "Doctor",
      "text": "We got the foot X-ray back. No signs of bone infection, which is good. But there are changes from neuropathy and old fractures."
    },
    {
      "turn_number": 35,
      "time": "2193-10-25 15:01:00",
      "speaker": "Patient",
      "text": "So no osteomyelitis?"
    },
    {
      "turn_number": 36,
      "time": "2193-10-25 15:02:00",
      "speaker": "Doctor",
      "text": "Not on the X-ray. If there’s still concern later, we might do an MRI, but for now, we’ll treat it as a soft tissue infection."
    },
    {
      "turn_number": 37,
      "time": "2193-10-26 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Afebrile, pain controlled, eating and walking. We’re planning for discharge tomorrow if all stays stable."
    },
    {
      "turn_number": 38,
      "time": "2193-10-26 09:01:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. What about the vancomycin?"
    },
    {
      "turn_number": 39,
      "time": "2193-10-26 09:02:00",
      "speaker": "Doctor",
      "text": "You’ll get IV vancomycin on dialysis days until your follow-up. We’ve sent the prescription to your dialysis center."
    },
    {
      "turn_number": 40,
      "time": "2193-10-26 09:03:00",
      "speaker": "Patient",
      "text": "And my foot dressing?"
    },
    {
      "turn_number": 41,
      "time": "2193-10-26 09:04:00",
      "speaker": "Doctor",
      "text": "Keep the offloading pad on. Change the outer wrap if it gets dirty. See your podiatrist soon."
    },
    {
      "turn_number": 42,
      "time": "2193-10-27 10:00:00",
      "speaker": "Doctor",
      "text": "All your labs are stable. We’re comfortable discharging you tomorrow morning."
    },
    {
      "turn_number": 43,
      "time": "2193-10-27 10:01:00",
      "speaker": "Patient",
      "text": "What should I watch for at home?"
    },
    {
      "turn_number": 44,
      "time": "2193-10-27 10:02:00",
      "speaker": "Doctor",
      "text": "Call if you have fever, increased redness or drainage from the foot, or numbness or coldness in your leg. Also, watch the groin site for bleeding."
    },
    {
      "turn_number": 45,
      "time": "2193-10-27 10:03:00",
      "speaker": "Patient",
      "text": "And if the groin bleeds a lot?"
    },
    {
      "turn_number": 46,
      "time": "2193-10-27 10:04:00",
      "speaker": "Doctor",
      "text": "Lie down, keep your leg straight, and press firmly for 10 minutes. If it doesn’t stop, go to the ER."
    },
    {
      "turn_number": 47,
      "time": "2193-10-27 10:05:00",
      "speaker": "Patient",
      "text": "Got it."
    },
    {
      "turn_number": 48,
      "time": "2193-10-28 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—you’re cleared to go home today. We’ll review your discharge instructions."
    },
    {
      "turn_number": 49,
      "time": "2193-10-28 08:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better."
    },
    {
      "turn_number": 50,
      "time": "2193-10-28 08:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Continue all your usual meds except we’ve added IV vancomycin on dialysis days."
    },
    {
      "turn_number": 51,
      "time": "2193-10-28 08:03:00",
      "speaker": "Patient",
      "text": "And aspirin—discharge says 325 mg, but I was on 81 mg."
    },
    {
      "turn_number": 52,
      "time": "2193-10-28 08:04:00",
      "speaker": "Doctor",
      "text": "Good catch. For now, stay on 81 mg unless your surgeon says otherwise. I’ll correct that."
    },
    {
      "turn_number": 53,
      "time": "2193-10-28 08:05:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 54,
      "time": "2193-10-28 08:06:00",
      "speaker": "Doctor",
      "text": "You can walk, shower, and do light activity. No heavy lifting for a week. And don’t drive while on pain meds."
    },
    {
      "turn_number": 55,
      "time": "2193-10-28 08:07:00",
      "speaker": "Patient",
      "text": "I’ll have help at home."
    },
    {
      "turn_number": 56,
      "time": "2193-10-28 08:08:00",
      "speaker": "Doctor",
      "text": "Good. Follow up with Dr. Lee for your endarterectomy. We’ll admit you two days before to start heparin."
    },
    {
      "turn_number": 57,
      "time": "2193-10-28 08:09:00",
      "speaker": "Patient",
      "text": "I’ll mark it on my calendar."
    },
    {
      "turn_number": 58,
      "time": "2193-10-28 08:10:00",
      "speaker": "Doctor",
      "text": "One last thing—elevate your leg when sitting to reduce swelling."
    },
    {
      "turn_number": 59,
      "time": "2193-10-28 08:11:00",
      "speaker": "Patient",
      "text": "I’ll use pillows like last time."
    },
    {
      "turn_number": 60,
      "time": "2193-10-28 08:12:00",
      "speaker": "Doctor",
      "text": "Perfect. You’ve done well. We’ll see you soon for surgery."
    },
    {
      "turn_number": 61,
      "time": "2193-10-29 09:00:00",
      "speaker": "Doctor",
      "text": "The discharge papers are ready. You can leave once transport arrives."
    },
    {
      "turn_number": 62,
      "time": "2193-10-29 09:01:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I appreciate everything."
    },
    {
      "turn_number": 63,
      "time": "2193-10-29 09:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you next week."
    },
    {
      "turn_number": 64,
      "time": "2193-10-29 09:03:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 65,
      "time": "2193-10-29 09:04:00",
      "speaker": "Doctor",
      "text": "Remember, call if you have any concerns before your surgery."
    },
    {
      "turn_number": 66,
      "time": "2193-10-29 09:05:00",
      "speaker": "Patient",
      "text": "I will, I promise."
    },
    {
      "turn_number": 67,
      "time": "2193-10-29 09:06:00",
      "speaker": "Doctor",
      "text": "Your dialysis center has your vancomycin order. They’ll give it on your next session."
    },
    {
      "turn_number": 68,
      "time": "2193-10-29 09:07:00",
      "speaker": "Patient",
      "text": "Good. I go Tuesday."
    },
    {
      "turn_number": 69,
      "time": "2193-10-29 09:08:00",
      "speaker": "Doctor",
      "text": "Perfect. That’s when the antibiotic is due."
    },
    {
      "turn_number": 70,
      "time": "2193-10-29 09:09:00",
      "speaker": "Patient",
      "text": "I feel ready."
    },
    {
      "turn_number": 71,
      "time": "2193-10-29 09:10:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. Keep up the good work."
    },
    {
      "turn_number": 72,
      "time": "2193-10-29 09:11:00",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    },
    {
      "turn_number": 73,
      "time": "2193-10-29 09:12:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Have a safe trip home."
    },
    {
      "turn_number": 74,
      "time": "2193-10-29 09:13:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 75,
      "time": "2193-10-29 09:14:00",
      "speaker": "Doctor",
      "text": "We’ll see you soon for your surgery."
    },
    {
      "turn_number": 76,
      "time": "2193-10-29 09:15:00",
      "speaker": "Patient",
      "text": "Looking forward to it."
    },
    {
      "turn_number": 77,
      "time": "2193-10-29 09:16:00",
      "speaker": "Doctor",
      "text": "Take it easy until then."
    },
    {
      "turn_number": 78,
      "time": "2193-10-29 09:17:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 79,
      "time": "2193-10-29 09:18:00",
      "speaker": "Doctor",
      "text": "Rest and eat well."
    },
    {
      "turn_number": 80,
      "time": "2193-10-29 09:19:00",
      "speaker": "Patient",
      "text": "I’ll try."
    },
    {
      "turn_number": 81,
      "time": "2193-10-29 09:20:00",
      "speaker": "Doctor",
      "text": "You’ve done great. We’re proud of your progress."
    },
    {
      "turn_number": 82,
      "time": "2193-10-29 09:21:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. That means a lot."
    },
    {
      "turn_number": 83,
      "time": "2193-10-29 09:22:00",
      "speaker": "Doctor",
      "text": "You’re welcome. See you next week."
    },
    {
      "turn_number": 84,
      "time": "2193-10-29 09:23:00",
      "speaker": "Patient",
      "text": "See you then."
    },
    {
      "turn_number": 85,
      "time": "2193-10-29 09:24:00",
      "speaker": "Doctor",
      "text": "Take care."
    }
  ],
  "summary": {
    "admission_start": "2193-10-21 16:05:00",
    "admission_end": "2193-10-29 11:44:00",
    "summary_paragraph": "A 60-year-old woman with end-stage renal disease, type 1 diabetes, and a mechanical heart valve was admitted for evaluation and treatment of a non-healing left foot ulcer with dry gangrene. She underwent a diagnostic left lower extremity angiogram, which revealed a near-occlusive lesion in the left superficial femoral artery. She remained hemodynamically stable throughout her stay, with no complications from the procedure. IV vancomycin was continued for infection prophylaxis, and anticoagulation was managed with a heparin drip that was discontinued once her INR reached a therapeutic level of 3.1. She was discharged home with instructions to continue oral medications, receive IV vancomycin on dialysis days, and follow up for a scheduled left femoral endarterectomy. The patient tolerated a regular diet, ambulated independently, and had stable vital signs at discharge.",
    "problems": [
      "Atherosclerosis of native arteries of the extremities with gangrene",
      "End stage renal disease",
      "Complications of transplanted kidney",
      "Pancreas replaced by transplant",
      "Systolic heart failure, unspecified",
      "Congestive heart failure, unspecified",
      "Diabetes mellitus without mention of complication, type II or unspecified type, not stated as uncontrolled",
      "Anemia, unspecified",
      "Coronary atherosclerosis of unspecified type of vessel, native or graft",
      "Aortocoronary bypass status",
      "Old myocardial infarction",
      "Percutaneous transluminal coronary angioplasty status",
      "Heart valve replaced by other means",
      "Long-term (current) use of anticoagulants",
      "Long-term (current) use of aspirin",
      "Renal dialysis status"
    ]
  }
}
